    def update_user_info(self, name, current, step):
        self.canvas.itemconfig(self.texts['name'], text=name.split()[0])  # Show only first name
        # format numeric values safely: API may return strings
        try:
            current_val = float(current)
            current_text = f"{current_val:.2f}"
        except Exception:
            current_text = str(current) if current is not None else ""
        self.canvas.itemconfig(self.texts["current"], text=current_text)
        self.canvas.itemconfig(self.texts["step"], text=step)
        time.sleep(0.1)  # Brief pause to allow UI update
        self.window.update_idletasks()

    def update_step(self, step):
        self.canvas.itemconfig(self.texts["step"], text=step)
        time.sleep(0.1)  # Brief pause to allow UI update
        self.window.update_idletasks()

    def update_earned_new(self, earned, new):
        try:
            earned_val = float(earned)
            earned_text = f"{earned_val:.2f}"
        except Exception:
            earned_text = str(earned) if earned is not None else ""
        try:
            new_val = float(new)
            new_text = f"{new_val:.2f}"
        except Exception:
            new_text = str(new) if new is not None else ""
        self.canvas.itemconfig(self.texts["earned"], text=earned_text)
        self.canvas.itemconfig(self.texts["new"], text=new_text)
        time.sleep(0.1)  # Brief pause to allow UI update
        self.window.update_idletasks()

    def update_timer(self, timer_text):
        self.canvas.itemconfig(self.texts["timer"], text=timer_text)
        time.sleep(0.1)  # Brief pause to allow UI update
        self.window.update_idletasks()

    def await_user(self):
        # Clear text items by setting their text explicitly
        self.canvas.itemconfig(self.texts["name"], text="")
        self.canvas.itemconfig(self.texts["current"], text="")
        self.canvas.itemconfig(self.texts["earned"], text="")
        self.canvas.itemconfig(self.texts["new"], text="")
        self.canvas.itemconfig(self.texts["step"], text="Tap your ID.")
        time.sleep(0.1)  # Brief pause to allow UI update
        self.window.update_idletasks()

    def show_fatal_error(self, message="EcoPrint RVM is temporarily unavailable.\nSorry for the inconvenience."):
        """
        Clears the entire canvas and displays a large centered icon and error message.
        Used when the machine encounters a critical failure.
        """
        try:
            # Remove all existing widgets/items from the canvas
            self.canvas.delete("all")

            # Recreate background (black)
            self.canvas.create_rectangle(0, 0, 1600, 900, fill="#E6B402", outline="")

            # Load and show large error image in center
            error_image = PhotoImage(file=Path(__file__).parent / "assets/frame0/fatal_error_icon.png")
            self.canvas.create_image(800, 350, image=error_image)

            # Keep reference to prevent garbage collection
            self.error_image_ref = error_image

            # Add centered text below the image
            self.canvas.create_text(
                800,
                650,
                text=message,
                fill="#000000",
                font=("Roboto", 32, "bold"),
                justify="center",
                anchor="center",
                width=1000
            )

            self.window.update_idletasks()
        except Exception as e:
            print(f"[GUI] Failed to display fatal error screen: {e}")
            traceback.print_exc()

    

    def run(self):
        self.window.mainloop()
